insert into generic_program_profiles (id, program_code, name, description, profils, typical_courses, leads_to_program_categories, factual_career_examples, source_url, last_verified_at, name_en, description_en, aliases) values
  ('de136ff3-99f3-5ac3-9607-cfa3e0498aae', '300.A0', 'Sciences humaines', 'Programme préuniversitaire visant à comprendre les comportements humains, les structures sociales, l''économie, la politique et l''histoire. Il prépare aux études universitaires dans plus de 200 programmes de sciences humaines, lettres, droit, éducation et administration.', '[{"id":"admin_gestion","name":"Administration, économie et gestion","nameEn":"Commerce, Administration & Economics","description":"Met l''accent sur les mathématiques collégiales préalables (calcul différentiel, calcul intégral et algèbre linéaire), la gestion d''entreprise, la comptabilité et la macroéconomie.","descriptionEn":"Emphasizes prerequisite collegial mathematics (differential calculus, integral calculus, and linear algebra), business management, accounting, and macroeconomics.","offeredAtCegeps":["Cégep de Sainte-Foy","Cégep Garneau","Cégep Limoilou","Champlain St. Lawrence","Centre d''études collégiales en Charlevoix"],"cegepOfferingsList":[{"cegepShortCode":"sainte-foy","cegepName":"Cégep de Sainte-Foy","profilNameFr":"Parcours Gestion","profilNameEn":"Management Track","descriptionFr":"Approfondit les mathématiques préalables complètes, l''analyse économique et la gestion organisationnelle.","descriptionEn":"Deepens prerequisite mathematics, economic analysis, and organizational management.","mathRequirement":"with_math","specialFeaturesFr":["Cheminement en 4 ou 5 sessions","Participation au concours de cas en gestion"],"specialFeaturesEn":["4 or 5 semester pathway","Business case competition participation"],"specificCourses":[{"code":"201-103-RE","nameFr":"Calcul différentiel (Sciences humaines)","nameEn":"Differential Calculus","ponderation":"3-2-3","prerequisiteFor":"Préalable universitaire BAA / Économie"},{"code":"201-203-RE","nameFr":"Calcul intégral (Sciences humaines)","nameEn":"Integral Calculus","ponderation":"3-2-3","prerequisiteFor":"Préalable universitaire"},{"code":"201-105-RE","nameFr":"Algèbre linéaire et vectorielle","nameEn":"Linear Algebra","ponderation":"3-2-3","prerequisiteFor":"Préalable universitaire"},{"code":"401-101-RE","nameFr":"L''entreprise et son environnement de gestion","nameEn":"Business Management","ponderation":"2-1-3"},{"code":"401-201-RE","nameFr":"Comptabilité financière et analyse d''états financiers","nameEn":"Financial Accounting","ponderation":"2-2-2"},{"code":"383-201-RE","nameFr":"Macroéconomie et marchés financiers","nameEn":"Macroeconomics","ponderation":"2-1-3"}]},{"cegepShortCode":"garneau","cegepName":"Cégep Garneau","profilNameFr":"Profil Administration, économie et gouvernance","profilNameEn":"Administration, Economics & Governance","descriptionFr":"Formation orientée vers la prise de décision, les finances de marché et la gestion des organisations publiques et privées.","descriptionEn":"Focused on decision-making, market finance, and public/private organizational management.","mathRequirement":"with_math","specialFeaturesFr":["Zone Sciences humaines","Simulations boursières et de gouvernance"],"specialFeaturesEn":["Social Sciences Zone","Stock market and governance simulations"],"specificCourses":[{"code":"201-103-RE","nameFr":"Calcul différentiel","nameEn":"Differential Calculus","ponderation":"3-2-3","prerequisiteFor":"Préalable universitaire BAA"},{"code":"201-203-RE","nameFr":"Calcul intégral","nameEn":"Integral Calculus","ponderation":"3-2-3","prerequisiteFor":"Préalable universitaire"},{"code":"201-105-RE","nameFr":"Algèbre linéaire et géométrie vectorielle","nameEn":"Linear Algebra","ponderation":"3-2-3","prerequisiteFor":"Préalable universitaire"},{"code":"401-101-RE","nameFr":"Initiation aux affaires et marketing","nameEn":"Introduction to Business & Marketing","ponderation":"2-1-3"},{"code":"401-201-RE","nameFr":"Comptabilité et gestion financière","nameEn":"Accounting & Financial Management","ponderation":"2-2-2"}]},{"cegepShortCode":"limoilou","cegepName":"Cégep Limoilou","profilNameFr":"Profil Relations économiques et administration (300.M1)","profilNameEn":"Economic Relations & Administration","descriptionFr":"DEC complet avec préalables en mathématiques pour l''accès direct aux facultés d''administration des affaires (FSA Laval, HEC, etc.).","descriptionEn":"Complete DEC with math prerequisites for direct university admission in business administration.","mathRequirement":"with_math","specialFeaturesFr":["Passerelles universitaires FSA Laval","Projet entrepreneurial en équipe"],"specialFeaturesEn":["FSA Laval university pathways","Team entrepreneurial project"],"specificCourses":[{"code":"201-103-RE","nameFr":"Calcul différentiel","nameEn":"Differential Calculus","ponderation":"3-2-3","prerequisiteFor":"Préalable universitaire BAA"},{"code":"201-203-RE","nameFr":"Calcul intégral","nameEn":"Integral Calculus","ponderation":"3-2-3","prerequisiteFor":"Préalable universitaire"},{"code":"201-105-RE","nameFr":"Algèbre linéaire","nameEn":"Linear Algebra","ponderation":"3-2-3","prerequisiteFor":"Préalable universitaire"},{"code":"401-101-RE","nameFr":"Gestion des organisations et entrepreneuriat","nameEn":"Organizational Management","ponderation":"2-1-3"}]},{"cegepShortCode":"champlain-slc","cegepName":"Champlain College St. Lawrence","profilNameFr":"Commerce Option (Profil Commerce / Affaires)","profilNameEn":"Commerce Option (Business Profile)","descriptionFr":"Programme anglophone axé sur le calcul collégial, la comptabilité et les études de cas en gestion d''entreprise.","descriptionEn":"English-language pre-university commerce curriculum covering calculus, accounting, and business case analysis.","mathRequirement":"with_math","specialFeaturesFr":["Compétitions intercollégiales de cas de commerce","Milieu 100% anglophone à Québec"],"specialFeaturesEn":["Intercollegiate business case competitions","Full English-language collegiate environment in Quebec City"],"specificCourses":[{"code":"201-103-RE","nameFr":"Calculus I (Differential)","nameEn":"Calculus I (Differentia