  ('8c33bfcf-488b-5c91-94a1-2cdb05cb814c', '200.B0', 'Sciences de la nature', 'Programme préuniversitaire rigoureux couvrant les mathématiques différentielles et intégrales, la physique, la chimie et la biologie. Il donne accès à tous les programmes universitaires contingentés en santé (médecine, pharmacie, dentaire), en génie et en sciences fondamentales.', '[{"id":"sante_vie","name":"Sciences de la santé et de la vie","nameEn":"Health & Life Sciences Profile","description":"Spécifiquement conçu pour les facultés de santé humaine et animale. Comprend les cours avancés d''anatomie et physiologie humaines, de chimie organique des biomolécules et de biologie cellulaire.","descriptionEn":"Specifically tailored for university faculties of human and animal health. Includes advanced human anatomy & physiology, organic chemistry of biomolecules, and cellular biology.","offeredAtCegeps":["Cégep de Sainte-Foy","Cégep Garneau","Cégep Limoilou","Champlain St. Lawrence","Centre d''études collégiales en Charlevoix","Campus Notre-Dame-de-Foy","Collège Mérici"],"cegepOfferingsList":[{"cegepShortCode":"sainte-foy","cegepName":"Cégep de Sainte-Foy","profilNameFr":"Profil Sciences et santé","profilNameEn":"Health & Science Profile","descriptionFr":"Approche intégrée de la santé globale avec cours de Biologie cellulaire dès la première session.","descriptionEn":"Integrated health curriculum with Cell Biology taught in the very first semester.","mathRequirement":"with_math","specialFeaturesFr":["Biologie cellulaire dès la session 1","Laboratoires d''anatomie et de biochimie de pointe"],"specialFeaturesEn":["Cell Biology from 1st semester","Cutting-edge anatomy and biochemistry labs"],"specificCourses":[{"code":"101-SN2-RE","nameFr":"Anatomie et physiologie humaines","nameEn":"Human Anatomy and Physiology","ponderation":"3-2-3","prerequisiteFor":"Préalable universitaire Médecine (MD), Dentaire (DMD), Pharmacie"},{"code":"202-SN3-RE","nameFr":"Chimie organique et biomolécules","nameEn":"