-- No overall cutoff column: universities publish multi-year ranges, or min/max/average,
-- never one canonical number, so every figure lives in cutoff_history with its own year
-- and figure type. admission_type is 'other' until each programme's process is sourced.
on conflict (catalog_slug) do update set
  university_id = excluded.university_id,
  name = excluded.name,
  source_url = excluded.source_url,
  last_verified_at = excluded.last_verified_at;

-- source_type is 'other' until CutoffEntry records where each figure was read (official PDF,
-- cégep compilation, BCI); source_tier and the programme's own source URL are carried.
on conflict (university_program_id, admission_year, figure_type) do update set
  cutoff = excluded.cutoff,
  source_tier = excluded.source_tier,
  source_url = excluded.source_url,
  verified_at = excluded.verified_at;

-- Prerequisites resolve through the same parser the app uses (resolvePrerequisite): only
-- NY-catalogue courses get a row; an alternative outside the catalogue is not a row here.
on conflict (university_program_id, course_id) do update set
  required = excluded.required;

-- cluster 4: bursaries (the in-region set; BURSARIES_OUT_OF_REGION waits for docs/02 Phase 7)
on conflict (catalog_slug) do update set
  name = excluded.name,
  source_org = excluded.source_org,
  cegep_id = excluded.cegep_id,
  category = excluded.category,
  amount_min = excluded.amount_min,
  amount_max = excluded.amount_max,
  deadline_type = excluded.deadline_type,
  deadline_date = excluded.deadline_date,
  application_url = excluded.application_url,
  eligible_university_programs = excluded.eligible_university_programs,
  min_r_score = excluded.min_r_score,
  min_session = excluded.min_session,
  requires_essay = excluded.requires_essay,
  requires_recommendation = excluded.requires_recommendation,
  tag_criteria = excluded.tag_criteria,
  last_verified_at = excluded.last_verified_at,
  eligible_cegep_program_codes = excluded.eligible_cegep_program_codes,
  deadline_precision = excluded.deadline_precision,
  source_url = excluded.source_url;

-- cluster 5: deadlines
on conflict (catalog_slug) do update set
  type = excluded.type,
  title = excluded.title,
  date = excluded.date,
  source_url = excluded.source_url,
  last_verified_at = excluded.last_verified_at,
  title_en = excluded.title_en,
  detail = excluded.detail,
  detail_en = excluded.detail_en,
  program_slugs = excluded.program_slugs,
  category = excluded.category;

-- cluster 8: generic programme profiles
on conflict (program_code) do update set
  name = excluded.name,
  description = excluded.description,
  profils = excluded.profils,
  typical_courses = excluded.typical_courses,
  leads_to_program_categories = excluded.leads_to_program_categories,
  factual_career_examples = excluded.factual_career_examples,
  source_url = excluded.source_url,
  last_verified_at = excluded.last_verified_at,
  name_en = excluded.name_en,
  description_en = excluded.description_en,
  aliases = excluded.aliases;

-- what /api/reference/version reports for this data
on conflict (version) do update set generated_at = excluded.generated_at, row_counts = excluded.row_counts;

commit;
